// Plain data and small modules keep a future TypeScript migration straightforward.
export const uid = () => crypto.randomUUID();
export const tabs = {home:['⌂','Visão geral'],notes:['▤','Notas & documentos'],characters:['♙','Personagens'],plot:['⌘','Trama & plot'],bestiary:['♧','Bestiário'],maps:['♧','Atlas de mapas'],globe:['◎','Globo 3D'],calendar:['▦','Calendário'],connections:['◇','Conexões'],timeline:['⌁','Linha do tempo'],scenes:['✎','Cenas']};
const now=()=>new Date().toISOString();
export function createWorld(name='As crônicas de Eldoria',demo=false){const id=uid(), f1=uid(),f2=uid();return {id,name,subtitle:demo?'Fantasia épica':'Um novo universo',theme:'light',palette:'sapphire',typography:'editorial',enabled:Object.keys(tabs),folders:demo?[{id:f1,name:'O mundo de Eldoria'},{id:f2,name:'Ideias & inspirações'}]:[],notes:demo?[{id:uid(),title:'O início de tudo',folder:f1,body:'<p>Antes que os reinos tivessem nomes, o mundo era uma única floresta.</p><h2>Uma promessa esquecida</h2><p>Nas ruínas de um antigo santuário, uma jovem cartógrafa encontra um mapa que muda a cada amanhecer. As cidades desenhadas nele ainda não existem — mas algumas começam a desaparecer.</p><blockquote>E se conhecer o caminho fosse justamente o que nos impede de encontrá-lo?</blockquote><p>Uma história sobre pertencimento, memória e a coragem de partir.</p>',updated:now()},{id:uid(),title:'A magia tem um preço',folder:f1,body:'<h2>As regras do impossível</h2><p>Toda magia exige uma lembrança. Quanto maior o feitiço, mais preciosa a memória que se perde.</p><ul><li>A magia não pode criar vida.</li><li>Um nome verdadeiro nunca pode ser esquecido.</li><li>As florestas guardam o que os homens perderam.</li></ul>',updated:now()},{id:uid(),title:'Fragmentos de uma jornada',folder:f2,body:'<p>O cheiro de chuva sobre as pedras. Uma canção que ninguém se lembra de ter aprendido. O último fogo aceso antes da travessia.</p>',updated:now()}]:[],characters:demo?[{id:uid(),name:'Lyra Ventoalto',role:'Protagonista',species:'Humana',age:'24',description:'Uma cartógrafa que desenha lugares com os quais sonha. Curiosa, obstinada e incapaz de deixar um mistério para trás.',motivation:'Encontrar o irmão que desapareceu além das montanhas.',conflict:'Teme que cada novo mapa apague uma parte de sua própria história.',image:''},{id:uid(),name:'Aren do Vale',role:'Aliado',species:'Elfo',age:'137',description:'Guardião das fronteiras da floresta. Conhece todas as trilhas, mas perdeu o caminho de casa.',motivation:'Restaurar as memórias de seu povo.',conflict:'Precisa confiar em quem aprendeu a temer.',image:''}]:[],bestiary:demo?[{id:uid(),name:'Cervo das estrelas',role:'Espírito ancestral',species:'Criatura mágica',age:'Desconhecida',description:'Dizem que suas galhadas sustentam fragmentos do céu. Surge entre as árvores apenas quando alguém precisa encontrar o caminho.',motivation:'Floresta dos Sussurros',conflict:'Luz astral, orientação e cura. Desaparece diante de fogo.',image:'assets/stag.jpg'}]:[],plot:demo?[{id:uid(),title:'O mapa impossível',description:'Lyra encontra um mapa que revela cidades que ainda não existem.',act:'Ato I',status:'idea'},{id:uid(),title:'A travessia da floresta',description:'Uma aliança improvável se forma entre a cartógrafa e o guardião do vale.',act:'Ato II',status:'writing'},{id:uid(),title:'O último nome',description:'No coração da montanha, uma escolha mudará o destino de Eldoria.',act:'Ato III',status:'idea'}]:[],maps:[{id:uid(),name:demo?'Eldoria, o mundo conhecido':'Meu primeiro mapa',image:'assets/eldoria.svg',pins:demo?[{id:uid(),name:'Floresta dos Sussurros',x:22,y:33,description:'Uma floresta tão antiga quanto o mundo. Entre suas árvores, as memórias perdidas ganham voz. Nenhum viajante atravessa suas trilhas sem deixar algo de si para trás.',image:'assets/forest.jpg'},{id:uid(),name:'Porto de Alvorada',x:31,y:56,description:'O início de todas as jornadas. Um porto de mercadores, histórias e promessas.',image:'assets/journey.jpg'}]:[]}],updated:now()};}
export function prepareWorld(w){if(!w.overview||typeof w.overview!=='object'||Array.isArray(w.overview))w.overview={};if(!Array.isArray(w.overview.quickTabs))w.overview.quickTabs=['notes','characters','maps','scenes'];if(!w.narrative){w.narrative={relations:[],events:[],scenes:[],calendar:{months:['Aurora','Bruma','Florália','Solalto','Âmbar','Geada'].map(name=>({name,days:30})),weekdays:['Sol','Lua','Estrela','Terra','Vento'],era:'Era atual'}};for(const t of ['connections','timeline','scenes'])if(Array.isArray(w.enabled)&&!w.enabled.includes(t))w.enabled.push(t);}if(w.calendarEvents===undefined){w.calendarEvents=[];if(Array.isArray(w.enabled)&&!w.enabled.includes('calendar'))w.enabled.push('calendar');}if(!Array.isArray(w.calendarEvents))throw Error('Calendário inválido.');if(!Array.isArray(w.folderNotes)){if(w.folderNotes!==undefined)throw Error('Documentos de pasta inválidos.');const notes=Array.isArray(w.notes)?w.notes:[];w.folderNotes=notes.filter(n=>n.folder);w.notes=notes.filter(n=>!n.folder);}return w;}
export function load(){try{const d=JSON.parse(localStorage.getItem('aethra.v1'));if(d?.worlds?.length){d.worlds.forEach(w=>{prepareWorld(w);w.theme??=d.theme==='dark'?'dark':'light';w.palette??=['sapphire','pond','aurora'].includes(d.palette)?d.palette:'sapphire';w.typography??=['editorial','literary','modern'].includes(d.typography)?d.typography:'editorial';});return d;}}catch{}const w=createWorld(undefined,true);return {version:1,worlds:[w]};}
export const state=load();
export const world=()=>prepareWorld(state.worlds.find(w=>w.id===state.current)||state.worlds[0]);
export function save(){world().updated=now();try{localStorage.setItem('aethra.v1',JSON.stringify(state));document.querySelector('#saveStatus').innerHTML='<i></i> Tudo salvo';return true;}catch{document.querySelector('#saveStatus').textContent='Armazenamento cheio';window.dispatchEvent(new CustomEvent('storagefull'));return false;}}
export const escapeHTML=(value='')=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function sanitize(html){
const d=new DOMParser().parseFromString(html,'text/html');
const allowed=new Set(['P','BR','DIV','SPAN','B','STRONG','I','EM','U','S','STRIKE','H1','H2','H3','UL','OL','LI','BLOCKQUOTE','A','FONT','SUP','SUB','CODE','MARK','HR','INPUT']);
for(const el of [...d.body.querySelectorAll('*')]){
if(['SCRIPT','STYLE','IFRAME','OBJECT','IMG','SVG','MATH'].includes(el.tagName)){el.remove();continue;}
if(!allowed.has(el.tagName)){el.replaceWith(...el.childNodes);continue;}
if(el.tagName==='INPUT'&&el.getAttribute('type')!=='checkbox'){el.remove();continue;}
let cleanStyle='';if(el.hasAttribute('style')){const safe=document.createElement('span');for(const property of ['color','background-color','font-size','font-family','font-weight','font-style','text-decoration','text-align','line-height','margin-left']){const value=el.style.getPropertyValue(property);if(!value||/[;{}<>]|url|var\(|expression|!important/i.test(value))continue;if(property==='font-size'&&!/^(?:[89]|[1-6][0-9]|7[0-2])px$/.test(value))continue;if(property==='line-height'&&!/^(1|1\.25|1\.5|1\.75|2|2\.5)$/.test(value))continue;if(property==='margin-left'&&!/^(?:0|40|80|120|160)px$/.test(value))continue;if(property==='font-family'&&!/^(?:Georgia|Arial|Verdana|Courier New|monospace|serif|sans-serif|["']Courier New["'])$/i.test(value))continue;safe.style.setProperty(property,value);}cleanStyle=safe.getAttribute('style')||'';}
for(const attr of [...el.attributes]){const keep=el.tagName==='A'&&attr.name==='href'&&(/^(https?:|mailto:)/i.test(attr.value)||/^#document\/[a-z\d%_-]+$/i.test(attr.value))||el.tagName==='FONT'&&attr.name==='color'&&/^#[\da-f]{3,8}$/i.test(attr.value)||el.tagName==='FONT'&&attr.name==='face'&&/^(Georgia|Arial|Verdana|Courier New)$/i.test(attr.value)||el.tagName==='FONT'&&attr.name==='size'&&/^[1-7]$/.test(attr.value)||el.tagName==='UL'&&attr.name==='data-checklist'||el.tagName==='INPUT'&&['type','checked','data-task','contenteditable'].includes(attr.name);if(!keep)el.removeAttribute(attr.name);}
if(cleanStyle)el.setAttribute('style',cleanStyle);
if(el.tagName==='A'){if(el.getAttribute('href')?.startsWith('#document/'))el.removeAttribute('target');else{el.setAttribute('target','_blank');el.setAttribute('rel','noopener noreferrer');}}
if(el.tagName==='INPUT'){el.type='checkbox';el.setAttribute('data-task','');el.setAttribute('contenteditable','false');el.setAttribute('aria-label','Marcar tarefa');}
}d.body.querySelectorAll('span:empty,font:empty,p:empty,ul:empty,ol:empty').forEach(el=>el.remove());for(const li of [...d.body.querySelectorAll('li')]){if(!['UL','OL'].includes(li.parentElement?.tagName)){const list=document.createElement('ul');if(li.querySelector('input[data-task]'))list.setAttribute('data-checklist','');li.before(list);list.append(li);}}return d.body.innerHTML;
}
export const plain=html=>new DOMParser().parseFromString(html,'text/html').body.textContent||'';
export function imageURL(src){return /^(assets\/[\w.-]+|data:image\/(png|jpeg|webp);base64,[a-z\d+/=\s]+)$/i.test(src||'')?src:'';}
export async function imageFile(file){if(!file?.type.startsWith('image/'))throw Error('Escolha um arquivo de imagem.');if(file.size>25*1024*1024)throw Error('A imagem deve ter até 25 MB.');const bitmap=await createImageBitmap(file);const scale=Math.min(1,1800/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();return canvas.toDataURL('image/jpeg',.85);}
